def _db_path(ws: Path) -> Path:
    return Path(ws).resolve().parent / "system" / "servicenow_grc" / "state.db"


def _norm(value) -> str:
    text = "" if value is None else str(value)
    text = text.replace("&", " and ")
    return re.sub(r"[^a-z0-9]+", " ", text.lower()).strip()


def _contains_all(text: str, phrases) -> bool:
    normalized = _norm(text)
    return all(_norm(phrase) in normalized for phrase in phrases)


def _date_present(text: str, year: int, month: int, day: int) -> bool:
    normalized = _norm(text)
    iso = f"{year:04d} {month:02d} {day:02d}"
    month_names = [
        "january", "february", "march", "april", "may", "june",
        "july", "august", "september", "october", "november", "december",
    ]
    natural = f"{month_names[month - 1]} {day} {year}"
    short = f"{month_names[month - 1][:3]} {day} {year}"
    return iso in normalized or natural in normalized or short in normalized


def _semantic_disposition(text: str) -> bool:
    normalized = _norm(text)
    has_missing_checksum = (
        "missing checksum" in normalized
        or "checksum is missing" in normalized
        or "checksum missing" in normalized
        or "checksum status missing" in normalized
        or "checksum status is missing" in normalized
    )
    has_condition = has_missing_checksum and (
        "superseded" in normalized or "orphaned" in normalized
    )
    has_retention = (
        "audit follow up" in normalized
        or "follow up item" in normalized
        or ("retain" in normalized and "follow up" in normalized)
    )
    has_invalidity = (
        "invalid final approval evidence" in normalized
        or "invalid as final approval evidence" in normalized
        or "not valid final approval evidence" in normalized
        or "not valid as final approval evidence" in normalized
        or "cannot establish final approval" in normalized
        or "does not establish final approval" in normalized
        or "cannot serve as final approval evidence" in normalized
        or "cannot be used as final approval evidence" in normalized
        or bool(re.search(
            r"(?:do not|does not|cannot|not be|must not be).{0,100}"
            r"(?:rely on|use|treat(?:ed)?|serve as|establish).{0,100}"
            r"final approval evidence",
            normalized,
        ))
    )
    return has_condition and has_retention and has_invalidity


def _semantic_governance(text: str) -> bool:
    normalized = _norm(text)
    has_committee = "travelers expense allocation steering committee" in normalized
    has_date = _date_present(text, 2025, 9, 26)
    has_activation = (
        "2025 q4" in normalized or "fourth quarter 2025" in normalized
    ) and ("management reporting" in normalized or "activation" in normalized)
    has_statutory = "fy2024" in normalized or "fiscal year 2024" in normalized
    has_gaap = "u s gaap" in normalized or "us gaap" in normalized
    has_no_restatement = (
        "will not be restated" in normalized
        or "not restated" in normalized
        or "no restatement" in normalized
        or "no fy2024 restatement" in normalized
    )
    return has_committee and has_date and has_activation and has_statutory and has_gaap and has_no_restatement


def _attestation_rows(ws: Path):
    path = _db_path(ws)
    if not path.exists():
        return []
    with sqlite3.connect(path) as connection:
        connection.row_factory = sqlite3.Row
        exists = connection.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' AND name='control_attestations'"
        ).fetchone()
        if not exists:
            return []
        return [dict(row) for row in connection.execute("SELECT * FROM control_attestations")]


def _audit_rows(ws: Path):
    path = _db_path(ws)
    if not path.exists():
        return []
    with sqlite3.connect(path) as connection:
        connection.row_factory = sqlite3.Row
        exists = connection.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' AND name='grc_audit_events'"
        ).fetchone()
        if not exists:
            return []
        return [dict(row) for row in connection.execute("SELECT * FROM grc_audit_events")]


def _memo_candidates(ws: Path):
    folder = Path(ws) / "03_Governance_and_Approval"
    results = []
    for path in sorted(folder.glob("*.docx")):
        try:
            document = Document(path)
            parts = [paragraph.text for paragraph in document.paragraphs]
            for table in document.tables:
                for row in table.rows:
                    parts.append(" | ".join(cell.text for cell in row.cells))
            text = "\n".join(parts)
        except Exception:
            continue
        if EVIDENCE_ID.lower() in text.lower():
            results.append((path, text))
    return results


def check_evidence_certification_recorded(ws):
    rows = _attestation_rows(Path(ws))
    if len(rows) != 1:
        return {"score": 0, "detail": f"Expected exactly one control attestation, found {len(rows)}"}
    row = rows[0]
    expected = {
        "case_id": CASE_ID,
        "evidence_id": EVIDENCE_ID,
        "attestation_type": "Evidence Certification",
        "status": "Accepted",
        "attested_by_party_id": EXPECTED_PARTY_ID,
        "attested_by_name": EXPECTED_NAME,
        "attestation_date": EXPECTED_DATE,
    }
    mismatches = {
        key: {"expected": value, "actual": row.get(key)}
        for key, value in expected.items()
        if _norm(row.get(key)) != _norm(value)
    }
    if mismatches:
        return {"score": 0, "detail": f"Certification fields do not match: {mismatches}"}
    return {"score": 1, "detail": f"Certification {row.get('attestation_id')} has the required identity, party, status, and date"}


def check_certification_rationale_complete(ws):
    rows = _attestation_rows(Path(ws))
    if len(rows) != 1:
        return {"score": 0, "detail": "A unique certification is required before its rationale can be checked"}
    notes = rows[0].get("notes") or ""
    if not _semantic_disposition(notes):
        return {"score": 0, "detail": "Certification notes do not fully preserve the missing-checksum, retained-follow-up, and invalid-final-evidence disposition"}
    if not _semantic_governance(notes):
        return {"score": 0, "detail": "Certification notes do not fully preserve the final approval, activation, and no-restatement conclusions"}
    return {"score": 1, "detail": "Certification notes preserve the complete evidence and governance rationale"}


def check_audit_event_linked(ws):
    attestations = _attestation_rows(Path(ws))
    audits = _audit_rows(Path(ws))
    if len(attestations) != 1 or len(audits) != 1:
        return {"score": 0, "detail": f"Expected one attestation and one audit event, found {len(attestations)} and {len(audits)}"}
    attestation = attestations[0]
    audit = audits[0]
    ok = (
        _norm(audit.get("event_type")) == _norm("CONTROL_ATTESTATION_RECORDED")
        and _norm(audit.get("record_id")) == _norm(attestation.get("attestation_id"))
        and _norm(audit.get("case_id")) == _norm(CASE_ID)
        and _norm(audit.get("actor_party_id")) == _norm(EXPECTED_PARTY_ID)
        and str(audit.get("event_date") or "").startswith(EXPECTED_DATE)
        and _contains_all(audit.get("details") or "", ["Evidence Certification", "Accepted"])
    )
    if not ok:
        return {"score": 0, "detail": f"Audit event is not correctly linked: {audit}"}
    return {"score": 1, "detail": f"Audit event {audit.get('audit_event_id')} is correctly linked to the certification"}


