def _hash_file(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _table_digest(connection: sqlite3.Connection, table: str):
    rows = connection.execute(f'SELECT * FROM "{table}"').fetchall()
    payload = "\n".join(sorted(repr(tuple(row)) for row in rows)).encode()
    return hashlib.sha256(payload).hexdigest()


def check_original_sources_and_history_unchanged(ws):
    ws = Path(ws)
    for relative, expected_hash in ORIGINAL_FILE_HASHES.items():
        path = ws / relative
        if not path.exists():
            return {"score": 0, "detail": f"Original workspace file was deleted: {relative}"}
        if _hash_file(path) != expected_hash:
            return {"score": 0, "detail": f"Original workspace file was modified: {relative}"}

    current_path = ws.resolve().parent / "system" / "servicenow_grc" / "state.db"
    if not current_path.exists():
        return {"score": 0, "detail": "ServiceNow GRC state database is missing"}
    with sqlite3.connect(current_path) as current:
        current_tables = {
            row[0] for row in current.execute(
                "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'"
            )
        }
        allowed_tables = set(SERVICENOW_BASELINE_TABLE_DIGESTS) | {
            "control_attestations", "grc_audit_events"
        }
        unexpected = sorted(current_tables - allowed_tables)
        if unexpected:
            return {"score": 0, "detail": f"Unexpected ServiceNow GRC tables were added: {unexpected}"}
        for table, expected_digest in SERVICENOW_BASELINE_TABLE_DIGESTS.items():
            if table not in current_tables:
                return {"score": 0, "detail": f"Historical ServiceNow GRC table was removed: {table}"}
            if _table_digest(current, table) != expected_digest:
                return {"score": 0, "detail": f"Historical or unrelated data changed in servicenow_grc.{table}"}
    return {"score": 1, "detail": "All original workspace files and all pre-existing database tables are unchanged"}
